arguments.content:
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2128;
  --bg-card: #161b22;
  --bg-card-hover: #1c2128;
  --bg-code: #0d1117;
  --border: #30363d;
  --border-hover: #475f91;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #58e6a0;
  --accent-hover: #3dd68c;
  --accent-blue: #475f91;
  --accent-blue-light: #6b8abf;
  --accent-cyan: #56d4e8;
  --accent-purple: #a78bfa;
  --font-display: 'Space Grotesk', sans-serif;
  --font-body: 'Plus Jakarta Sans', sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
  --radius: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --transition: 200ms ease;
  --max-width: 1280px;
  --sidebar-width: 260px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a { color: var(--accent-blue-light); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-cyan); }

h1, h2, h3, h4 { font-family: var(--font-display); font-weight: 700; line-height: 1.2; }

code, pre { font-family: var(--font-mono); }

/* ── GRAIN OVERLAY ── */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.04'/%3E%3C/svg%3E");
  pointer-events: none;
  z-index: 9999;
  opacity: 0.4;
}

/* ── TOP NAV ── */
.topnav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.topnav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
}

.topnav-logo {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 18px;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 10px;
  white-space: nowrap;
}

.topnav-logo svg { flex-shrink: 0; }

.topnav-links {
  display: flex;
  align-items: center;
  gap: 8px;
  list-style: none;
}

.topnav-links a {
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: var(--radius);
  transition: all var(--transition);
}

.topnav-links a:hover,
.topnav-links a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.topnav-right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.topnav-search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 6px 12px;
  font-size: 13px;
  color: var(--text-muted);
  cursor: pointer;
  transition: border-color var(--transition);
}

.topnav-search:hover { border-color: var(--border-hover); }

.topnav-search kbd {
  background: var(--bg-tertiary);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 6px;
  font-size: 11px;
  font-family: var(--font-mono);
  color: var(--text-muted);
}

.btn-login {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 6px 14px;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: transparent;
  cursor: pointer;
  transition: all var(--transition);
}

.btn-login:hover { color: var(--text-primary); border-color: var(--border-hover); }

.hamburger {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 4px;
}

/* ── HERO ── */
.hero {
  position: relative;
  padding: 80px 24px 60px;
  text-align: center;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -40%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 800px;
  background: radial-gradient(ellipse, rgba(71, 95, 145, 0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(88, 230, 160, 0.1);
  border: 1px solid rgba(88, 230, 160, 0.2);
  color: var(--accent);
  font-size: 13px;
  font-weight: 600;
  padding: 6px 16px;
  border-radius: 100px;
  margin-bottom: 24px;
  font-family: var(--font-mono);
}

.hero h1 {
  font-size: 52px;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--text-secondary) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 680px;
  margin: 0 auto 36px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ── BUTTONS ── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  padding: 10px 22px;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
}

.btn-primary {
  background: var(--accent);
  color: #0d1117;
}

.btn-primary:hover { background: var(--accent-hover); color: #0d1117; transform: translateY(-1px); }

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border);
}

.btn-secondary:hover { border-color: var(--accent); color: var(--accent); }

.btn-ghost {
  background: transparent;
  color: var(--accent-blue-light);
  padding: 10px 16px;
}

.btn-ghost:hover { color: var(--accent-cyan); background: rgba(86, 212, 232, 0.05); }

/* ── SECTION ── */
.section {
  padding: 72px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-header {
  margin-bottom: 48px;
}

.section-header h2 {
  font-size: 32px;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.section-header p {
  font-size: 16px;
  color: var(--text-secondary);
  max-width: 600px;
}

.section-divider {
  border: none;
  border-top: 1px solid var(--border);
  max-width: var(--max-width);
  margin: 0 auto;
}

/* ── CARDS ── */
.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.card-grid-2 { grid-template-columns: repeat(2, 1fr); }

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.card:hover {
  border-color: var(--border-hover);
  background: var(--bg-card-hover);
  transform: translateY(-2px);
}

.card-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 20px;
}

.card-icon-green { background: rgba(88, 230, 160, 0.1); color: var(--accent); }
.card-icon-blue { background: rgba(71, 95, 145, 0.15); color: var(--accent-blue-light); }
.card-icon-cyan { background: rgba(86, 212, 232, 0.1); color: var(--accent-cyan); }
.card-icon-purple { background: rgba(167, 139, 250, 0.1); color: var(--accent-purple); }

.card h3 {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: 8px;
}

.card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 16px;
}

.card-link {
  font-size: 14px;
  font-weight: 600;
  color: var(--accent-blue-light);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.card-link:hover { color: var(--accent-cyan); gap: 10px; }

.card-glow::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
}

.card-glow-green::before { background: linear-gradient(90deg, transparent, var(--accent), transparent); }
.card-glow-blue::before { background: linear-gradient(90deg, transparent, var(--accent-blue-light), transparent); }
.card-glow-cyan::before { background: linear-gradient(90deg, transparent, var(--accent-cyan), transparent); }
.card-glow-purple::before { background: linear-gradient(90deg, transparent, var(--accent-purple), transparent); }

/* ── PRODUCT CARDS ── */
.product-cards { padding: 48px 24px 72px; }

.product-cards .card-grid {
  max-width: var(--max-width);
  margin: 0 auto;
}

/* ── CLI SETUP ── */
.cli-section {
  padding: 72px 24px;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.cli-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: start;
}

.cli-left h2 {
  font-size: 32px;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.cli-left > p {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 0;
}

/* ── ACCORDION ── */
.accordion {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.accordion-item {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition);
}

.accordion-item.active { border-color: var(--accent); }

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  background: var(--bg-card);
  border: none;
  color: var(--text-primary);
  font-family: var(--font-body);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition);
}

.accordion-trigger:hover { background: var(--bg-card-hover); }

.accordion-trigger svg {
  transition: transform var(--transition);
  flex-shrink: 0;
  color: var(--text-muted);
}

.accordion-item.active .accordion-trigger svg {
  transform: rotate(180deg);
  color: var(--accent);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease;
}

.accordion-content-inner {
  padding: 18px;
  border-top: 1px solid var(--border);
}

.accordion-content-inner ol {
  list-style: none;
  counter-reset: steps;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 16px;
}

.accordion-content-inner ol li {
  counter-increment: steps;
  display: flex;
  gap: 12px;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.accordion-content-inner ol li::before {
  content: counter(steps);
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: rgba(88, 230, 160, 0.1);
  color: var(--accent);
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
}

/* ── TABS ── */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--bg-primary);
  border-radius: var(--radius) var(--radius) 0 0;
  overflow: hidden;
  border: 1px solid var(--border);
  border-bottom: none;
}

.tab-btn {
  flex: 1;
  padding: 10px 16px;
  background: var(--bg-tertiary);
  border: none;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
}

.tab-btn:hover { color: var(--text-secondary); }
.tab-btn.active { background: var(--bg-code); color: var(--accent); }

.tab-content {
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
  padding: 16px 18px;
}

.tab-panel { display: none; }
.tab-panel.active { display: block; }

.code-block {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--accent);
  white-space: pre-wrap;
  word-break: break-all;
  line-height: 1.7;
}

.code-block .cmd { color: var(--accent-cyan); }
.code-block .flag { color: var(--accent-purple); }
.code-block .pkg { color: var(--text-primary); }

.code-inline {
  font-family: var(--font-mono);
  font-size: 13px;
  background: rgba(88, 230, 160, 0.08);
  color: var(--accent);
  padding: 2px 8px;
  border-radius: 4px;
  border: 1px solid rgba(88, 230, 160, 0.15);
}

/* ── LAUNCH CTA ── */
.launch-section {
  padding: 72px 24px;
}

.launch-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.launch-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}

.launch-card:hover {
  border-color: var(--border-hover);
  transform: translateY(-2px);
}

.launch-card h3 {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 10px;
}

.launch-card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 20px;
}

/* ── COMMUNITY ── */
.community-section {
  padding: 72px 24px;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
}

.community-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  transition: all var(--transition);
  cursor: pointer;
}

.community-card:hover {
  border-color: var(--accent-blue);
  transform: translateY(-2px);
}

.community-card h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.community-card p {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.5;
}

/* ── FOOTER ── */
.footer {
  border-top: 1px solid var(--border);
  padding: 60px 24px 40px;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
}

.footer-col h5 {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-col a {
  font-size: 14px;
  color: var(--text-secondary);
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding-top: 24px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--text-muted);
}

/* ── SIDEBAR LAYOUT ── */
.docs-layout {
  display: flex;
  min-height: calc(100vh - 64px);
}

.sidebar {
  width: var(--sidebar-width);
  background: var(--bg-secondary);
  border-right: 1px solid var(--border);
  padding: 24px 0;
  position: sticky;
  top: 64px;
  height: calc(100vh - 64px);
  overflow-y: auto;
  transition: width 300ms ease, padding 300ms ease, opacity 300ms ease;
  flex-shrink: 0;
}

.sidebar.collapsed {
  width: 0;
  padding: 24px 0;
  overflow: hidden;
  opacity: 0;
}

.sidebar-toggle {
  position: absolute;
  left: var(--sidebar-width);
  top: 80px;
  z-index: 10;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  color: var(--text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 300ms ease;
}

.sidebar.collapsed ~ .sidebar-toggle {
  left: 0;
}

.sidebar-toggle:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border-color: var(--border-hover);
}

.sidebar-section {
  padding: 0 16px;
  margin-bottom: 24px;
}

.sidebar-section h6 {
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 10px;
  padding: 0 12px;
}

.sidebar-link {
  display: block;
  padding: 7px 12px;
  font-size: 14px;
  color: var(--text-secondary);
  border-radius: var(--radius);
  transition: all var(--transition);
}

.sidebar-link:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.sidebar-link.active {
  color: var(--accent);
  background: rgba(88, 230, 160, 0.06);
}

.docs-content {
  flex: 1;
  min-width: 0;
  padding: 40px 48px 72px;
  max-width: 960px;
  transition: margin 300ms ease;
}

.docs-content h1 {
  font-size: 40px;
  letter-spacing: -0.02em;
  margin-bottom: 16px;
}

.docs-content > p.lead {
  font-size: 17px;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 48px;
  max-width: 680px;
}

.docs-section { margin-bottom: 56px; }

.docs-section h2 {
  font-size: 26px;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
  padding-top: 8px;
}

.docs-section > p {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 24px;
  max-width: 640px;
}

.mini-card-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 14px;
}

.mini-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  transition: all var(--transition);
}

.mini-card:hover {
  border-color: var(--border-hover);
  background: var(--bg-card-hover);
}

.mini-card h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.mini-card p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.mini-card-grid-3 { grid-template-columns: repeat(3, 1fr); }

/* ── BEST PRACTICES ── */
.bp-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}

.bp-item {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  transition: all var(--transition);
}

.bp-item:hover { border-color: var(--border-hover); }

.bp-item h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 4px;
}

.bp-item p {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.4;
}

/* ── PROTOCOL ACTORS ── */
.actors-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 24px;
}

.actor-node {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
