  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-col a {
  font-size: 14px;
  color: var(--text-secondary);
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  max-width: var(--max-width);
  margin: 40px auto 0;
  padding-top: 24px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: var(--text-muted);
}

/* ── SIDEBAR LAYOUT ── */
.docs-layout {
  display: flex;
  min-height: calc(100vh - 64px);
}

.sidebar {
  width: var(--sidebar-width);
  background: var(--bg-secondary);
  border-right: 1px solid var(--border);
  padding: 24px 0;
  position: sticky;
  top: 64px;
  height: calc(100vh - 64px);
  overflow-y: auto;
  transition: width 300ms ease, padding 300ms ease, opacity 300ms ease;
  flex-shrink: 0;
}

.sidebar.collapsed {
  width: 0;
  padding: 24px 0;
  overflow: hidden;
  opacity: 0;
}

.sidebar-toggle {
  position: absolute;
  left: var(--sidebar-width);
  top: 80px;
  z-index: 10;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  color: var(--text-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 300ms ease;
}

.sidebar.collapsed ~ .sidebar-toggle {
  left: 0;
}

.sidebar-toggle:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border-color: var(--border-hover);
}

.sidebar-section {
  padding: 0 16px;
  margin-bottom: 24px;
}

.sidebar-section h6 {
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 10px;
  padding: 0 12px;
}

.sidebar-link {
  display: block;
  padding: 7px 12px;
  font-size: 14px;
  color: var(--text-secondary);
  border-radius: var(--radius);
  transition: all var(--transition);
}

.sidebar-link:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.sidebar-link.active {
  color: var(--accent);
  background: rgba(88, 230, 160, 0.06);
}

.docs-content {
  flex: 1;
  min-width: 0;
  padding: 40px 48px 72px;
  max-width: 960px;
  transition: margin 300ms ease;
}

.docs-content h1 {
  font-size: 40px;
  letter-spacing: -0.02em;
  margin-bottom: 16px;
}

.docs-content > p.lead {
  font-size: 17px;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 48px;
  max-width: 680px;
}

.docs-section { margin-bottom: 56px; }

.docs-section h2 {
  font-size: 26px;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
  padding-top: 8px;
}

.docs-section > p {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 24px;
  max-width: 640px;
}

.mini-card-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 14px;
}

.mini-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  transition: all var(--transition);
}

.mini-card:hover {
  border-color: var(--border-hover);
  background: var(--bg-card-hover);
}

.mini-card h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.mini-card p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.mini-card-grid-3 { grid-template-columns: repeat(3, 1fr); }

/* ── BEST PRACTICES ── */
.bp-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}

.bp-item {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  transition: all var(--transition);
}

.bp-item:hover { border-color: var(--border-hover); }

.bp-item h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 4px;
}

.bp-item p {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.4;
}

/* ── PROTOCOL ACTORS ── */
.actors-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 24px;
}

.actor-node {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
}

.actor-node:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
}

.actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(88, 230, 160, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 12px;
  font-size: 20px;
}

.actor-node h4 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.actor-node p { font-size: 12px; color: var(--text-muted); }

/* ── COMING SOON BADGE ── */
.badge-soon {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  background: rgba(167, 139, 250, 0.1);
  border: 1px solid rgba(167, 139, 250, 0.2);
  color: var(--accent-purple);
  font-size: 12px;
  font-weight: 600;
  font-family: var(--font-mono);
  border-radius: 100px;
}

/* ── SUPPORT ── */
.support-hero {
  text-align: center;
  padding: 80px 24px 48px;
}

.support-hero h1 {
  font-size: 44px;
  margin-bottom: 16px;
}

.support-hero p {
  font-size: 17px;
  color: var(--text-secondary);
  max-width: 560px;
  margin: 0 auto 28px;
}

.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  max-width: 800px;
  margin: 0 auto;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
}

.support-card:hover { border-color: var(--border-hover); }

.support-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 8px;
}

.support-card p {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.contact-section {
  text-align: center;
  padding: 48px 24px 72px;
  max-width: 600px;
  margin: 0 auto;
}

.contact-section p {
  font-size: 15px;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

/* ── ANIMATIONS ── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-up {
  animation: fadeUp 600ms ease forwards;
  opacity: 0;
}

.fade-up-1 { animation-delay: 100ms; }
.fade-up-2 { animation-delay: 200ms; }
.fade-up-3 { animation-delay: 300ms; }
.fade-up-4 { animation-delay: 400ms; }
.fade-up-5 { animation-delay: 500ms; }

/* ── RESPONSIVE ── */
@media (max-width: 1200px) {
  .cli-inner { grid-template-columns: 1fr; gap: 40px; }
  .footer-inner { grid-template-columns: repeat(2, 1fr); }
  .sidebar { width: 220px; }
  .sidebar.collapsed ~ .sidebar-toggle { left: 0; }
  .sidebar-toggle { left: 220px; }
}

@media (max-width: 768px) {
  .topnav-links { display: none; }
  .topnav-search { display: none; }
  .hamburger { display: flex; }

  .topnav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 64px;
    left: 0;
    right: 0;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border);
    padding: 16px;
    gap: 4px;
  }

  .topnav-links.mobile-open a {
    padding: 12px 16px;
    width: 100%;
  }

  .hero { padding: 48px 20px 40px; }
  .hero h1 { font-size: 32px; }
  .hero p { font-size: 15px; }
  .hero-ctas { flex-direction: column; align-items: center; }

  .card-grid { grid-template-columns: 1fr; }
  .card-grid-2 { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: 1fr; }
  .launch-grid { grid-template-columns: 1fr; }
  .mini-card-grid { grid-template-columns: 1fr; }
  .mini-card-grid-3 { grid-template-columns: 1fr; }
  .bp-grid { grid-template-columns: 1fr; }
  .actors-diagram { grid-template-columns: repeat(2, 1fr); }
  .support-grid { grid-template-columns: 1fr; }

  .section { padding: 48px 20px; }
  .section-header h2 { font-size: 26px; }

  .cli-section { padding: 48px 20px; }
  .cli-left h2 { font-size: 26px; }

  .footer-inner { grid-template-columns: 1fr; gap: 28px; }
  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }

  .sidebar { display: none; }
  .sidebar-toggle { display: none; }
  .docs-content { padding: 32px 20px 48px; }
  .docs-content h1 { font-size: 30px; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 28px; }
  .hero p { font-size: 14px; }
  .actors-diagram { grid-template-columns: 1fr; }
}
